const raw = $('DB | Load HubSpot Sync Context').item.json.sync_context;
const ctx = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!ctx || ctx.connector_key !== 'hubspot_primary') {
  throw new Error('HUBSPOT_SYNC_CONTEXT_INVALID');
}
let gate = ctx.reliability_gate;
if (typeof gate === 'string') {
  gate = JSON.parse(gate);
}
const allowed = gate?.allowed === true;
return {
  sync_context: ctx,
  should_sync: allowed,
  skip_reason: allowed ? null : 'RELIABILITY_CIRCUIT_OPEN',
  search_body: {
    filterGroups: [{
      filters: [
        { propertyName: 'hs_lastmodifieddate', operator: 'GTE', value: String(ctx.query_start_ms) },
        { propertyName: 'hs_lastmodifieddate', operator: 'LTE', value: String(ctx.query_end_ms) }
      ]
    }],
    sorts: ['hs_lastmodifieddate'],
    properties: [
      'dealname','amount','deal_currency_code','dealstage','hubspot_owner_id',
      'hs_analytics_source','createdate','closedate','hs_lastmodifieddate',
      'hs_is_closed','hs_is_closed_won'
    ],
    limit: 200
  }
};

const contextRaw = $('DB | Load HubSpot Sync Context').first().json.sync_context;
const ctx = typeof contextRaw === 'string' ? JSON.parse(contextRaw) : contextRaw;
const pages = $input.all().map(item => item.json ?? {});
const results = pages.flatMap(page => Array.isArray(page.results) ? page.results : []);
if (results.length > 10000) throw new Error('HUBSPOT_SYNC_RESULT_LIMIT_EXCEEDED');

const expectedCurrency = String(ctx.currency_code ?? '').trim().toUpperCase();
const records = [];
let rejectedCount = 0;
let earliestRejectedAt = null;

const parseDate = value => {
  if (value === null || value === undefined || value === '') return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const asBool = value => value === true || String(value).toLowerCase() === 'true';

for (const record of results) {
  const p = record?.properties ?? {};
  const sourceRecordId = String(record?.id ?? '').trim();
  const amount = Number(p.amount);
  const sourceCurrency = String(p.deal_currency_code ?? '').trim().toUpperCase();
  const currency = sourceCurrency || expectedCurrency;
  const stageName = String(p.dealstage ?? '').trim();
  const updatedAt = parseDate(p.hs_lastmodifieddate);
  const createdAt = parseDate(p.createdate);
  const closeDate = parseDate(p.closedate);
  const isWon = asBool(p.hs_is_closed_won);
  const isClosed = asBool(p.hs_is_closed);
  const stageCategory = isWon ? 'won' : (isClosed ? 'lost' : 'open');

  const valid =
    sourceRecordId.length > 0 && sourceRecordId.length <= 200 &&
    Number.isFinite(amount) && amount >= 0 &&
    /^[A-Z]{3}$/.test(currency) && currency === expectedCurrency &&
    stageName.length > 0 &&
    updatedAt !== null &&
    (stageCategory === 'open' || closeDate !== null);

  if (!valid) {
    rejectedCount += 1;
    const candidate = updatedAt ? new Date(updatedAt).getTime() : null;
    if (candidate !== null && (earliestRejectedAt === null || candidate < earliestRejectedAt)) {
      earliestRejectedAt = candidate;
    }
    continue;
  }

  records.push({
    source_record_id: sourceRecordId,
    source_payload: {
      dealname: p.dealname ?? null,
      amount: String(amount),
      deal_currency_code: currency,
      dealstage: stageName,
      hubspot_owner_id: p.hubspot_owner_id ?? null,
      hs_analytics_source: p.hs_analytics_source ?? null,
      createdate: createdAt,
      closedate: closeDate,
      hs_lastmodifieddate: updatedAt,
      revint_stage_category: stageCategory
    }
  });
}

const queryStart = new Date(ctx.query_start_at).getTime();
const queryEnd = new Date(ctx.query_end_at).getTime();
let watermarkMs = queryEnd;
if (rejectedCount > 0) {
  watermarkMs = earliestRejectedAt === null ? queryStart : Math.max(queryStart, earliestRejectedAt);
}

return [{
  json: {
    connector_key: 'hubspot_primary',
    query_start_at: new Date(queryStart).toISOString(),
    query_end_at: new Date(queryEnd).toISOString(),
    watermark: new Date(watermarkMs).toISOString(),
    source_count: results.length,
    record_count: records.length,
    rejected_count: rejectedCount,
    records,
    event_id: 'HUBSPOT-SYNC-' + String(queryEnd)
  }
}];
